parameters.jsCode:
const orderData = $('Obtener Datos del Pedido').item.json;
const courierData = $('Obtener Datos del Mensajero').item.json;

// Supabase devuelve arrays, tomar el primer elemento
const order = Array.isArray(orderData) ? orderData[0] : orderData;
const courier = Array.isArray(courierData) ? courierData[0] : courierData;

if (!order || !courier) {
  throw new Error('No se encontró el pedido o el mensajero');
}

const linkRastreo = `https://1012rastreo.1012studiocreativo.com/track/${order.tracking_token}`;

// Formatear el número de teléfono del cliente
// YCloud requiere formato internacional sin + ni espacios: 573XXXXXXXXX
let clientPhone = order.client_phone.replace(/[^0-9]/g, '');
if (clientPhone.startsWith('0')) clientPhone = '57' + clientPhone.slice(1);
if (!clientPhone.startsWith('57')) clientPhone = '57' + clientPhone;

return {
  json: {
    clientPhone,
    clientName: order.client_name,
    deliveryAddress: order.delivery_address,
    trackingLink: linkRastreo,
    courierName: courier.name,
    courierPhone: courier.phone,
    courierPlate: courier.plate || '',
    courierPhoto: courier.photo_url || '',
    orderId: order.id
  }
};

